from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'dist' / 'koncepcje'
A = '../../assets/'
PATHS = {
 'arrow': '<path d="M5 12h14M13 6l6 6-6 6"/>',
 'search': '<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',
 'gem': '<path d="m3 8 4-5h10l4 5-9 13Z M3 8h18M7 3l5 18 5-18"/>',
 'phone': '<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',
 'wallet': '<path d="M20 7H4V5l14-3v5M4 7v13h17V7Z"/><path d="M21 12h-7v5h7"/>',
 'tool': '<path d="m14 5 5-3a6 6 0 0 1-7 8L4 20l-3-3 10-8a6 6 0 0 1 8-7l-4 4Z"/>',
 'pin': '<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z"/><circle cx="12" cy="9" r="2"/>',
 'check': '<path d="m5 12 5 5L20 6"/>',
 'coin': '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="6"/><path d="M10 9h4l-4 6h4"/>',
 'bar': '<path d="m5 4 12 2 3 15-17-3Z M8 8l6 1M7 12l8 1"/>',
}
def icon(name='arrow'):
 return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{PATHS[name]}</svg>'
def action(label, href, secondary=False):
 return f'<a class="action{" secondary" if secondary else ""}" href="{href}">{label}{icon()}</a>'
def opener(label,key,cls='action'):
 return f'<button type="button" class="{cls}" data-open="{key}">{label}{icon()}</button>'
def image(file,alt,cls=''):
 return f'<img class="{cls}" src="{A}{file}" alt="{alt}">'
def calc():
 return f'''<form class="calc-form" data-calc>
 <div class="calc-inputs"><label>Kwota pożyczki, zł<input name="amount" type="number" min="50" max="100000" step="50" value="2000" inputmode="decimal" required></label><label>Okres pożyczki<select name="days"><option value="15">15 dni · 2,5%</option><option value="30">30 dni · 5%</option></select></label></div>
 <div class="calc-presets">{''.join(f'<button type="button" data-amount="{n}" aria-pressed="false">{n:,} zł</button>'.replace(',', ' ') for n in [500,1000,2000,5000,10000])}</div>
 <div class="calc-numbers" aria-live="polite"><div><span>Opłata</span><strong class="fee">50,00 zł</strong></div><div><span>Łącznie do spłaty</span><strong class="total">2 050,00 zł</strong></div></div><p class="calc-error" hidden>Podaj kwotę od 50 do 100 000 zł.</p>
 <a class="action calc-contact" href="https://wa.me/48601775146" target="_blank" rel="noopener">Zapytaj o pożyczkę{icon()}</a><p class="calc-note">Obliczenie orientacyjne według tabeli SEZAM dla 15 i 30 dni. Dokładny koszt i termin potwierdzamy przed podpisaniem umowy. Przy wyższych kwotach warunki ustalamy indywidualnie.</p></form>'''
def faq():
 entries=[('Co mogę przynieść pod zastaw?','Złoto i srebro, biżuterię, monety, sztabki, telefony, laptopy, konsole oraz sprzęt techniczny. Jeśli masz nietypowy przedmiot, opowiedz nam o nim przed wizytą.'),('Od czego zależy cena skupu złota?','Od próby, masy i parametrów przedmiotu oraz bieżących warunków rynkowych. Ostateczną wycenę przedstawiamy po sprawdzeniu przedmiotu w punkcie.'),('Czy mogę sprawdzić telefon przed zakupem?','Na miejscu możesz przyjrzeć się wybranemu urządzeniu, sprawdzić telefon i porozmawiać o szczegółach zakupu.')]
 return '<div class="faq">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in entries)+'</div>'
def hours():
 return '<div class="hours">Poniedziałek–piątek <b>10:00–18:00</b> <br>Sobota <b>10:00–14:00</b> <br>Niedziela — zamknięte<small>Godziny w święta potwierdź telefonicznie.</small></div>'
def links():
 return '<div class="contact-links">'+action('601 775 146','tel:+48601775146')+action('Napisz w WhatsApp','https://wa.me/48601775146',True)+'</div>'
def footer():
 return '<footer class="site-footer wrap"><span>© 2026 PUH SEZAM Sp. z o.o. · NIP 5993281276</span><span><a href="https://sezam.com.pl/" target="_blank" rel="noopener">Informacje o ofercie</a> · Grafiki aranżacyjne.</span></footer>'
def dialog():
 return '''<dialog id="detail-dialog" aria-labelledby="detail-title"><button class="dialog-close" type="button" aria-label="Zamknij">×</button><div class="dialog-label">SEZAM / WARTO WIEDZIEĆ</div><h2 id="detail-title"></h2><p id="detail-text"></p><div class="dialog-actions"><a id="detail-link" class="action" target="_blank" rel="noopener"></a><a id="detail-whatsapp" class="action secondary" target="_blank" rel="noopener">Napisz w WhatsApp</a></div></dialog>'''
def write(slug,title,body):
 dest=ROOT/slug;dest.mkdir(parents=True,exist_ok=True)
 (dest/'index.html').write_text(f'''<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="SEZAM Gorzów — skup złota, pożyczki pod zastaw, biżuteria i elektronika. Pocztowa 11."><title>{title}</title><link rel="icon" href="{A}favicon.svg"><link rel="stylesheet" href="../shared/base.css"><link rel="stylesheet" href="style.css"><script src="../shared/features.js" defer></script></head><body class="{slug}"><a class="skip-link" href="#main">Przejdź do treści</a>{body}{footer()}{dialog()}</body></html>''')

